function getFeatureResult(feature, experiment) {
    const real = experiment?.baseline_result?.features?.[feature];
    if (real) return real;
    return {
        target_summary: {
            median: 0,
            q25: 0,
            q75: 0,
            q90: 0,
            mean: 0
        },
        candidate_summary: {
            median: 0,
            q25: 0,
            q75: 0,
            q90: 0,
            mean: 0
        },
        distance: {
            normalized_distance: 0,
            pooled_iqr: 0,
            ks_statistic: 0,
            wasserstein: 0,
            sample_count_target: 0,
            sample_count_candidate: 0
        },
        definition: "Feature definition (experiment data unavailable)",
        units: "units"
    };
}
// --- Main component ---
function benchmarkFromStatus(status) {
    const BASE_ID = 100000;
    const available = status?.available_real_datasets ?? [];
    const unavailable = status?.unavailable_datasets ?? [];
    const datasets = [
        ...available.map((d, i)=>({
                id: BASE_ID + i,
                body: d.body,
                name: d.id,
                nominal_resolution: d.id === "moon_lola" ? "20 m/pixel" : "20 m pixel spacing",
                validation_status: "VALIDATED",
                access_status: "DOWNLOADED",
                kind: "real_observational"
            })),
        ...unavailable.map((d, i)=>({
                id: BASE_ID + available.length + i,
                body: d.body,
                name: d.id,
                validation_status: "REJECTED",
                access_status: "BLOCKED_BY_EARTHDATA_AUTHENTICATION",
                kind: "official_product"
            }))
    ];
    const coverage = {};
    for (const d of datasets)coverage[d.body] = (coverage[d.body] ?? 0) + 1;
    return {
        datasets,
        planet_coverage: coverage,
        real_benchmark_findings: [],
        limitation: "No independently labeled real benchmark dataset was available covering overlapping terrain across two+ DEM products. Existing datasets (moon_lola, mars_jezero_ctx_dtm) are validated observational products but cover different geographical regions. earth_nasadem_hgt_v001 is blocked by authentication. No dataset pair currently enables within-pair TMSI reproducibility testing."
    };
}
